/**
 * Result of the optional hardware key-attestation flow for AndroidKeyStore alias
 * `checkin_attestation`.
 *
 * GmsCore builds an EC P-256 / SHA-256 attestation key with
 * `KeyGenParameterSpec.Builder`, sets the challenge with
 * `setAttestationChallenge(...)`, and first tries normal AndroidKeyStore key generation. If that
 * fails with a matching `KeyStoreException` on a device advertising StrongBox support, it retries
 * with `setIsStrongBoxBacked(true)`.
 *
 * The integrity payload is the certificate chain at `certificate_chain_der`, not the challenge.
 * Per AOSP `KeyGenParameterSpec.Builder#setAttestationChallenge` javadoc: when the key lives in
 * secure hardware that supports attestation, "the certificate will be signed by a chain of
 * certificates rooted at a trustworthy CA key", so that hardware-rooted chain is what lets the
 * server verify the attested device properties and IDs.
 *
 * The attestation key and its certificate chain are short-lived. GmsCore sets
 * `setCertificateNotBefore` to one minute before generation time (a clock-skew buffer) and
 * `setCertificateNotAfter` to ten minutes after that, giving the cert a ~10-minute validity
 * window. The temporary `checkin_attestation` keystore entry is deleted after the chain is
 * read, so each checkin produces a fresh chain.
 *
 * The challenge value's only job is freshness. From the same javadoc: "The purpose of the
 * challenge value is to enable relying parties to verify that the key was created in response
 * to a specific request. If attestation is desired but no challenge is needed, any non-`null`
 * value may be used, including an empty byte array." Servers don't validate the content -- just
 * the signature over it. So on a synthesized request, any non-null challenge works.
 *
 * See:
 * https://developer.android.com/reference/android/security/keystore/KeyGenParameterSpec.Builder#setAttestationChallenge(byte[])
 *
 * For reference, GmsCore's actual derivation of the challenge bytes: with sibling flag
 * `take_challenge_from_server` enabled (the default), the 8-byte big-endian encoding of the
 * previous successful checkin response's stored server `time_ms` if available, otherwise the
 * 8-byte big-endian encoding of `Instant.now().toEpochMilli()`. When the flag is disabled, the
 * UTF-8 bytes of `Instant.now().toString()`. On a true first checkin no server `time_ms` has
 * been stored yet, so the challenge falls back to local time regardless of the flag.
 *
 * When `PackageManager.hasSystemFeature("android.software.device_id_attestation")` returns true,
 * GmsCore calls `setAttestationIds(...)` to bind unique device identifiers into the attestation
 * extension. In this checkin path that means SERIAL
 * and/or IMEI, never MEID: GmsCore passes `{ID_TYPE_IMEI, ID_TYPE_SERIAL}` when both are
 * available, `{ID_TYPE_SERIAL}` when only serial is available, `{ID_TYPE_IMEI}` when only IMEI is
 * available, and skips the call when neither is available.
 *
 * On the same builder, GmsCore also calls `setDevicePropertiesAttestationIncluded(true)`, which
 * adds `Build.BRAND`, `Build.DEVICE`, `Build.MANUFACTURER`, `Build.MODEL`, and `Build.PRODUCT` to
 * the attestation extension.
 *
 * The `setAttestationIds(...)` path requires
 * `android.permission.READ_PRIVILEGED_PHONE_STATE` (protection level
 * `signature|privileged|role`), and Keystore2 enforces that requirement during key generation.
 *
 * This checkin path does not call `setUniqueIdIncluded(true)`. If generation succeeds, GmsCore
 * reads the temporary `checkin_attestation` certificate chain back from AndroidKeyStore,
 * DER-encodes each certificate into `certificate_chain_der`, copies the challenge bytes into
 * `challenge_echo`, and deletes the temporary key entry.
 *
 * On failure (e.g. Sandboxed Google Play will fail to generate the `checkin_attestation` key due
 * to the `READ_PRIVILEGED_PHONE_STATE` requirement for `setAttestationIds`), GmsCore may still
 * send `hardware_revision` plus an `error` block instead of a certificate chain. However, the
 * server still accepts checkins that report a key generation failure.
 */
export interface KeyAttestationResult {
  /**
   * DER-encoded X.509 certificate chain returned by AndroidKeyStore, using
   * `Certificate.getEncoded()` for each certificate.
   */
  certificateChainDer: Uint8Array[];
  /**
   * Attestation challenge bytes given to `KeyGenParameterSpec.Builder.setAttestationChallenge(...)`
   *
   * In this checkin path, with `take_challenge_from_server` enabled (the default), the bytes
   * are the 8-byte big-endian encoding of milliseconds: the previous successful checkin
   * response's stored server `time_ms` when available, or `Instant.now().toEpochMilli()`
   * otherwise. When the flag is disabled, the bytes are the UTF-8 encoding of
   * `Instant.now().toString()` instead.
   */
  challengeEcho?:
    | Uint8Array
    | undefined;
  /** Hardware revision from `SystemProperties.get("ro.boot.hardware.revision", "")`. */
  hardwareRevision?:
    | string
    | undefined;
  /**
   * Error block sent when device ID attestation was attempted but key generation or
   * certificate creation failed.
   */
  error?: KeyAttestationError | undefined;
}

/** Error information for a failed key-attestation attempt. */
export interface KeyAttestationError {
  /** Numeric error code from `android.security.KeyStoreException.getNumericErrorCode()`. */
  errorCode?:
    | number
    | undefined;
  /**
   * Short human-readable error message.
   *
   * Truncated before sending.
   */
  errorMessage?: string | undefined;
}

